COMMENT ON SCHEMA public IS '';


--
-- Name: get_patient_blood_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_patient_blood_summary(patient_uuid uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE result JSON;
BEGIN
SELECT json_build_object(
        'patient_id',
        patient_uuid,
        'blood_group',
        p.blood_group,
        'blood_group_verified',
        p.blood_group_verified,
        'total_transfusions',
        (
            SELECT COUNT(*)
            FROM blood_transfusions
            WHERE patient_id = patient_uuid
        ),
        'total_reactions',
        (
            SELECT COUNT(*)
            FROM transfusion_reactions
            WHERE patient_id = patient_uuid
        ),
        'last_transfusion',
        (
            SELECT MAX(start_time)
            FROM blood_transfusions
            WHERE patient_id = patient_uuid
        ),
        'pending_requests',
        (
            SELECT COUNT(*)
            FROM blood_requests
            WHERE patient_id = patient_uuid
                AND status IN ('Pending', 'Approved')
        )
    ) INTO result
FROM patients p
WHERE p.id = patient_uuid;
RETURN result;
END;
$$;


