--
-- Name: aldrete_scores; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.aldrete_scores (
    id integer NOT NULL,
    record_id integer,
    "timestamp" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    activity_score integer,
    respiration_score integer,
    circulation_score integer,
    consciousness_score integer,
    o2_saturation_score integer,
    total_score integer GENERATED ALWAYS AS (((((activity_score + respiration_score) + circulation_score) + consciousness_score) + o2_saturation_score)) STORED,
    assessed_by character varying(100),
    CONSTRAINT aldrete_scores_activity_score_check CHECK (((activity_score >= 0) AND (activity_score <= 2))),
    CONSTRAINT aldrete_scores_circulation_score_check CHECK (((circulation_score >= 0) AND (circulation_score <= 2))),
    CONSTRAINT aldrete_scores_consciousness_score_check CHECK (((consciousness_score >= 0) AND (consciousness_score <= 2))),
    CONSTRAINT aldrete_scores_o2_saturation_score_check CHECK (((o2_saturation_score >= 0) AND (o2_saturation_score <= 2))),
    CONSTRAINT aldrete_scores_respiration_score_check CHECK (((respiration_score >= 0) AND (respiration_score <= 2)))
);


