    delegated_to_user_id integer,
    specialist_category_id integer,
    revenue_share_override integer,
    visit_schedule jsonb DEFAULT '{}'::jsonb,
    bank_details jsonb DEFAULT '{}'::jsonb,
    min_guarantee numeric(10,2) DEFAULT 0,
    payout_frequency character varying(20) DEFAULT 'monthly'::character varying,
    specialization text,
    qualification text,
    experience_years integer,
    profile_image text,
    available_days text,
    bio text,
    gender text,
    failed_login_count integer DEFAULT 0,
    locked_until timestamp with time zone,
    last_failed_ip character varying(45),
    last_login_at timestamp with time zone,
    last_login_ip character varying(45),
    is_2fa_enabled boolean DEFAULT false,
    CONSTRAINT users_role_check CHECK (((role)::text = ANY (ARRAY[('admin'::character varying)::text, ('doctor'::character varying)::text, ('nurse'::character varying)::text, ('receptionist'::character varying)::text, ('lab_tech'::character varying)::text, ('pharmacist'::character varying)::text, ('anaesthetist'::character varying)::text, ('billing'::character varying)::text, ('finance'::character varying)::text, ('super_admin'::character varying)::text, ('platform_admin'::character varying)::text])))
);

