--
-- Name: patient_transfusion_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.patient_transfusion_history AS
 SELECT bt.id AS transfusion_id,
    bt.transfusion_id AS transfusion_code,
    bt.patient_id,
    p.name AS patient_name,
    bu.unit_id AS unit_code,
    bu.blood_group,
    bct.name AS component_name,
    bct.code AS component_code,
    bt.start_time,
    bt.end_time,
    bt.volume_transfused,
    bt.outcome,
    bt.reaction_occurred,
    bt.reaction_type,
    bt.reaction_severity,
    u.name AS administered_by_name
   FROM ((((public.blood_transfusions bt
     LEFT JOIN public.patients p ON ((bt.patient_id = p.id)))
     LEFT JOIN public.blood_units bu ON ((bt.unit_id = bu.id)))
     LEFT JOIN public.blood_component_types bct ON ((bu.component_type_id = bct.id)))
     LEFT JOIN public.users u ON ((bt.administered_by = u.id)));


