--
-- Name: v_pos_offline_pending; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pos_offline_pending AS
 SELECT q.id,
    q.queue_id,
    q.invoice_id,
    q.device_id,
    q.amount,
    q.total_amount,
    q.payment_mode,
    q.customer_phone,
    q.customer_name,
    q.department,
    q.is_emi,
    q.emi_tenure,
    q.emi_bank,
    q.status,
    q.retry_count,
    q.max_retries,
    q.last_retry_at,
    q.error_message,
    q.synced_transaction_id,
    q.synced_at,
    q.created_by,
    q.created_at,
    q.updated_at,
    d.device_name,
    d.location,
    p.name AS provider_name
   FROM ((public.pos_offline_queue q
     LEFT JOIN public.pos_devices d ON ((q.device_id = d.id)))
     LEFT JOIN public.pos_providers p ON ((d.provider_id = p.id)))
  WHERE ((q.status)::text = ANY ((ARRAY['queued'::character varying, 'failed'::character varying])::text[]))
  ORDER BY q.created_at;


--
-- Name: v_tpa_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tpa_summary AS
 SELECT p.code,
    p.name,
    p.is_active,
    count(DISTINCT c.id) FILTER (WHERE ((c.status)::text = 'pending'::text)) AS pending_claims,
    count(DISTINCT c.id) FILTER (WHERE ((c.status)::text = 'approved'::text)) AS approved_claims,
    count(DISTINCT pa.id) FILTER (WHERE ((pa.status)::text = 'pending'::text)) AS pending_preauth,
    sum(c.approved_amount) FILTER (WHERE ((c.status)::text = ANY ((ARRAY['approved'::character varying, 'settled'::character varying])::text[]))) AS total_approved
   FROM ((public.tpa_providers p
     LEFT JOIN public.insurance_claims c ON ((c.provider_id = p.id)))
     LEFT JOIN public.insurance_preauth pa ON ((pa.provider_id = p.id)))
  GROUP BY p.id, p.code, p.name, p.is_active;


